<script setup lang="ts">
import {computed,nextTick,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import {ask} from '@tauri-apps/plugin-dialog';
import {api,type Table,type Trace,type Simulation,type Wire,exportText} from '../api';
import type {CaseSpec} from '../generated/CaseSpec';
import type {CaseContext} from '../generated/CaseContext';
import type {CaseReview} from '../generated/CaseReview';
import type {CaseGrade} from '../generated/CaseGrade';
import type {RepairValidation} from '../generated/RepairValidation';
import {useLab} from '../store';
import EvidenceBoard from '../components/EvidenceBoard.vue';
import {trapFocus} from '../accessibility';
import SqlEditor from '../components/SqlEditor.vue';
import ResultTable from '../components/ResultTable.vue';
import TraceView from '../components/TraceView.vue';
import SchedulePlayback from '../components/SchedulePlayback.vue';
import PredictionCheckpoint from '../components/PredictionCheckpoint.vue';
import {markdownTable} from '../report';
defineProps<{theme:string}>();const emit=defineEmits<{connect:[]}>();const lab=useLab();
const p=computed(()=>lab.workspace!.case_progress);const spec=ref<Wire<CaseSpec>>();const context=ref<Wire<CaseContext>>();const review=ref<Wire<CaseReview>>();const selected=ref(p.value.task||'capacity');const editor=ref<InstanceType<typeof SqlEditor>>();
const result=ref<{table:Table,snapshot:string}>();const executedSql=ref('');const grading=ref<Wire<CaseGrade>>();const trace=ref<Trace>();const simulation=ref<{source:string,simulation:Simulation}>();const repair=ref<Wire<RepairValidation>>();const strategy=ref('naive');const templates=ref('');const actual=ref<number>();const counter=ref<number>();const cause=ref('');const showPrediction=ref(true);const drawer=ref(false);const boardOpen=ref(false);const pinMessage=ref('');const latestCard=ref('');const drawerHost=ref<HTMLElement>();const boardButton=ref<HTMLButtonElement>();
const channels=['case-query','case-grade','case-trace','case-repair','case-close','case-simulation'];let timer:ReturnType<typeof setTimeout>|undefined;let alive=true;
const task=computed(()=>context.value?.tasks.find(t=>t.id===selected.value));const stale=computed(()=>!!spec.value&&p.value.version!==spec.value.version);const closed=computed(()=>p.value.closed&&p.value.closure_revision===2);const mode=computed(()=>p.value.mode||'guided');const nextTask=computed(()=>{const c=context.value;return c?c.tasks[c.stage]:undefined});
const completed=computed(()=>review.value?.items.filter(i=>['capacity','requests','timeline','reproduce','repair'].includes(i.id)&&i.passed).length??0);
function args(){return{case_id:spec.value!.id,version:spec.value!.version,seed:p.value.seed,task:selected.value,progress:JSON.parse(JSON.stringify(p.value)),engine:'sqlite'};}
function clear(){lab.invalidateJobs(channels);result.value=undefined;grading.value=undefined;trace.value=undefined;repair.value=undefined;}
async function refresh(){if(!spec.value||stale.value)return;const [c,r]=await Promise.all([lab.run<Wire<CaseContext>>('case-context','case_context',args()),lab.run<Wire<CaseReview>>('case-review','case_review',args())]);if(!alive)return;if(c){context.value=c;if(!c.tasks.some(t=>t.id===selected.value))selected.value=c.tasks[c.tasks.length-1]?.id??'capacity';}if(r)review.value=r;}
function changed(presentation=false){if(!presentation){p.value.closed=false;lab.invalidateJobs(['case-close','case-context','case-review']);review.value=undefined;clearTimeout(timer);timer=setTimeout(()=>void refresh(),350);}lab.markDirty();}
const answer=computed({get:()=>p.value.answers[selected.value]??(mode.value==='guided'?task.value?.starter:'')??'',set:(v:string)=>{if(v===answer.value)return;p.value.answers[selected.value]=v;clear();changed();}});
watch(selected,()=>{p.value.task=selected.value;showPrediction.value=true;clear();simulation.value=undefined;actual.value=undefined;counter.value=undefined;cause.value='';const saved=p.value.answers.reproduce;if(selected.value==='reproduce'&&saved){try{const a=JSON.parse(saved);actual.value=a.actual;counter.value=a.counter;cause.value=a.cause}catch{/* retain invalid text in saved answer */}}});
watch(drawer,async open=>{await nextTick();if(open)drawerHost.value?.focus();else boardButton.value?.focus();});
onMounted(async()=>{try{const s=await api<Wire<CaseSpec>>('case_catalog');if(!alive)return;spec.value=s;if(!p.value.version)p.value.version=s.version;await refresh();}catch(e){if(alive)lab.fail(e)}});
onBeforeUnmount(()=>{alive=false;clearTimeout(timer);lab.invalidateJobs([...channels,'case-context','case-review']);});
async function changeMode(value:string){p.value.mode=value;clear();changed();await refresh();}
async function run(){const original=answer.value;const sql=await editor.value?.source()??original;if(original!==answer.value)return;result.value=undefined;const r=await lab.run<{table:Table,snapshot:string}>('case-query','case_query',{...args(),sql});if(r){result.value=r;executedSql.value=sql;}}
async function grade(){const r=await lab.run<Wire<CaseGrade>>('case-grade','case_grade',{...args(),sql:answer.value});if(r){grading.value=r;p.value.answers[selected.value]=answer.value;if(r.status==='passed'&&!p.value.completed.includes(selected.value))p.value.completed.push(selected.value);changed();await refresh();}}
async function visualize(){const r=await lab.run<Trace>('case-trace','case_trace',{...args(),sql:answer.value});if(r)trace.value=r;}
function reproductionAnswer(){p.value.answers.reproduce=JSON.stringify({actual:actual.value,counter:counter.value,cause:cause.value});lab.invalidateJobs(['case-grade']);grading.value=undefined;changed();}
async function reproduce(){const r=await lab.run<{source:string,simulation:Simulation}>('case-simulation','case_reproduction',args());if(r)simulation.value=r;}
async function validate(mysql=false){const r=await lab.run<Wire<RepairValidation>>('case-repair',mysql?'case_repair_mysql':'case_repair',{...args(),strategy:strategy.value});if(r){repair.value=r;if(r.status==='passed'){if(mysql)p.value.mysql_strategy=r.strategy;else{p.value.model_strategy=r.strategy;if(!p.value.completed.includes('repair'))p.value.completed.push('repair');}changed();await refresh();}}}
async function loadTemplates(){try{templates.value=await api<string>('case_templates',args())}catch(e){lab.fail(e)}}
function pin(){if(!result.value)return;const card={id:crypto.randomUUID(),task:selected.value,sql:executedSql.value,table:{...result.value.table,rows:result.value.table.rows.slice(0,200),truncated:result.value.table.truncated||result.value.table.rows.length>200},case_version:spec.value!.version,seed:p.value.seed,snapshot:result.value.snapshot,note:'',hypothesis:'',links:[] as string[]};const size=(v:unknown)=>new TextEncoder().encode(JSON.stringify(v)).length;if(p.value.evidence.length>=20||size(card)>256*1024||size([...p.value.evidence,card])>4*1024*1024){lab.fail('证据上限：20 卡，每卡 200 行 / 256 KiB，总计 4 MiB。');return}p.value.evidence.push(card);p.value.board.cards[card.id]={x:30+(p.value.evidence.length-1)%3*350,y:30+Math.floor((p.value.evidence.length-1)/3)*310,view:'table',category:0,value:1};latestCard.value=card.id;pinMessage.value=`已固定证据 ${p.value.evidence.length.toString().padStart(2,'0')}，可在右侧或证据板查看。`;changed();}
function remove(id:string){p.value.evidence=p.value.evidence.filter(c=>c.id!==id);for(const c of p.value.evidence)c.links=c.links.filter(link=>link!==id);delete p.value.board.cards[id];p.value.board.relations=p.value.board.relations.filter(r=>r.from!==id&&r.to!==id);changed();}
async function source(id:string){const card=p.value.evidence.find(c=>c.id===id);if(!card)return;selected.value=card.task;await nextTick();answer.value=card.sql;drawer.value=false;boardOpen.value=false;await nextTick();editor.value?.focus();pinMessage.value='已恢复证据来源 SQL；重新运行产生新结果，原卡片仍保留原快照。';}
async function rerun(id:string){const card=p.value.evidence.find(c=>c.id===id);if(!card)return;if(card.case_version!==spec.value?.version||card.seed!==p.value.seed){lab.fail('历史证据请在当前调查中重新查询并固定');return}await source(id);await run();}
function jump(requirement:Wire<CaseReview>['items'][number]){if(context.value?.tasks.some(t=>t.id===requirement.task))selected.value=requirement.task;if(requirement.action==='board')boardOpen.value=true;else if(requirement.action==='evidence')drawer.value=true;}
async function close(){const r=await lab.run<Wire<CaseGrade>>('case-close','case_close',args());if(r){grading.value=r;if(r.status==='passed'){p.value.closed=true;p.value.closure_revision=2;lab.markDirty();}}}
async function preview(name:string){const sql=`SELECT * FROM "${name.replaceAll('"','""')}" LIMIT 100`;const r=await lab.run<{table:Table,snapshot:string}>('case-query','case_query',{...args(),sql});if(r){result.value=r;executedSql.value=sql;}}
function reportText(){return `# ${context.value?.title??spec.value?.title}\n\n调查轮次：${p.value.round+1}；数据版本：${p.value.version}；快照：${spec.value?.id}:${p.value.seed}\n\n状态：${closed.value?'已结案':'调查中'}\n\n根因：${p.value.cause||'未确定'}；模型：${p.value.model_strategy||'未通过'}；MySQL：${p.value.mysql_strategy||'未实测'}\n\n## 解释链\n\n`+p.value.board.relations.map(r=>`- ${r.from} → ${r.to} (${r.kind})`).join('\n')+'\n\n'+p.value.evidence.map(c=>`## ${c.task} · ${c.id}\n\n${c.note}\n\n来源：${c.snapshot}；支持：${c.hypothesis||'未关联'}\n\n\`\`\`sql\n${c.sql}\n\`\`\`\n\n${markdownTable(c.table)}`).join('\n\n')+'\n\n## 历史结论\n\n'+p.value.history.map(h=>`- 第 ${h.round+1} 轮：${h.closed?'已结案':'未结案'}；${h.cause}；模型 ${h.model_strategy}；MySQL ${h.mysql_strategy||'未实测'}`).join('\n');}
async function report(){await exportText(reportText(),'选课事故调查报告.md')}
async function restart(){if(p.value.history.length>=50){lab.fail('历史结论已达 50 轮，请导出报告并新建工程。');return}if(!await ask('保存本轮结论到历史，并开始新的调查轮次？当前证据可先导出报告。',{title:'新的调查轮次',kind:'info'}))return;const previous=p.value;p.value.history.push({round:previous.round,cause:previous.cause,model_strategy:previous.model_strategy,mysql_strategy:previous.mysql_strategy,closed:previous.closed,closure_revision:previous.closure_revision,evidence_count:previous.evidence.length});p.value.round++;p.value.seed++;p.value.version=spec.value!.version;p.value.task='capacity';p.value.answers={};p.value.completed=[];p.value.evidence=[];p.value.board={cards:{},relations:[],zoom:1,x:0,y:0};p.value.cause='';p.value.model_strategy='';p.value.mysql_strategy='';p.value.closed=false;p.value.closure_revision=0;selected.value='capacity';pinMessage.value='';clear();changed();await refresh();}
</script>
<template><div v-if="spec" class="case-page case-studio">
 <header class="case-heading"><div><span class="eyebrow">校园数据库调查档案 · CASE 01</span><h1>{{context?.title??spec.title}}</h1><p>{{context?.narrative??spec.briefing}}</p></div><div class="case-heading-actions"><label>调查方式<select :value="mode" aria-label="调查方式" @change="changeMode(($event.target as HTMLSelectElement).value)"><option value="guided">教学 · 逐步揭示</option><option value="expert">自主 · 自由调查</option></select></label><button ref="boardButton" data-testid="open-evidence" @click="drawer=true">证据 {{p.evidence.length}} / 20</button><button @click="report().catch(lab.fail)">导出报告</button></div></header>
 <div v-if="stale" class="notice warning">数据版本不一致，旧证据保留为历史。<button @click="restart">开始当前版本</button></div>
 <div v-if="p.closed&&p.closure_revision!==2" class="notice">旧版已结案记录已保留。请补全新版解释链后重新核验；原始证据和答案仍可使用。</div>
 <div v-if="pinMessage" class="pin-feedback" role="status">✓ {{pinMessage}} <button @click="boardOpen=true">查看调查板 →</button></div>
 <div class="case-layout"><aside class="case-materials"><details open><summary>案件资料 · {{completed}} / 5</summary><nav class="case-tasks"><button v-for="(t,i) in context?.tasks??[]" :key="t.id" :data-testid="`case-task-${t.id}`" :class="{active:selected===t.id}" @click="selected=t.id"><small>0{{i+1}}</small>{{t.title}}<span v-if="review?.items.find(r=>r.id===t.id)?.passed">✓</span></button></nav><p v-if="mode==='guided'&&(context?.tasks.length??0)<5" class="muted">下一份资料将在当前核验通过后开放。自主模式允许自行选择调查路径。</p><h3>可查数据库</h3><button v-for="r in context?.schema.relations??[]" :key="r.name" class="case-table-link" @click="preview(r.name)">{{r.name}} <small>前 100 行</small></button></details></aside>
 <section v-if="task&&!stale" class="case-work"><header><span class="eyebrow">当前调查目标</span><h2>{{task.title}}</h2><p>{{task.prompt}}</p></header>
 <template v-if="['capacity','requests','timeline'].includes(selected)"><div class="answer-editor"><SqlEditor ref="editor" :id="`case-${spec.id}-${p.seed}-${selected}`" v-model="answer" :schema="context!.schema" :theme="theme" @run="run"/></div><div class="toolbar"><button class="primary" data-testid="case-run" :disabled="!!lab.jobs['case-query']" @click="run">运行查询</button><button :disabled="!!lab.jobs['case-grade']" @click="grade">核验当前任务</button><button @click="visualize">解释查询过程</button><small>Ctrl+Enter 运行 · Ctrl+Shift+Enter 提交</small></div></template>
 <template v-else-if="selected==='reproduce'"><PredictionCheckpoint v-if="showPrediction&&mode==='guided'" id="oversubscription" @skip="showPrediction=false"/><button class="primary" @click="reproduce">回放请求交错过程</button><SchedulePlayback v-if="simulation" :source="simulation.source" :result="simulation.simulation"/><div class="structured-answer"><label>实际成功人数<input v-model.number="actual" type="number" @input="reproductionAnswer"></label><label>计数器值<input v-model.number="counter" type="number" @input="reproductionAnswer"></label><label>根因<select v-model="cause" @change="reproductionAnswer"><option value="">请选择</option><option value="stale_read">读取旧值后覆盖写入</option><option value="duplicate_name">同名学生被混淆</option><option value="null_count">NULL 计数问题</option></select></label><button @click="grade">验证复现结论</button></div></template>
 <template v-else><label>修复策略<select v-model="strategy" @change="lab.invalidateJobs(['case-repair']);repair=undefined"><option value="naive">原方案</option><option value="unique_only">单独唯一约束</option><option value="row_lock">课程行锁</option><option value="conditional_update">原子条件更新</option></select></label><div class="toolbar"><button class="primary" @click="validate(false)">枚举离线模型</button><button @click="emit('connect')">连接 MySQL</button><button @click="validate(true)">MySQL 实测</button><button @click="lab.page='transactions'">自由双会话实验</button></div><details @toggle="($event.target as HTMLDetailsElement).open&&!templates&&loadTemplates()"><summary>MySQL 修复模板及实验边界</summary><pre class="repair-templates">{{templates||'加载中…'}}</pre><p>离线模型限定两个请求。MySQL 在新建临时库中实测并清理；两种验证状态分别记录。</p></details><div v-if="repair" class="grade-card" :class="repair.status"><strong>{{repair.mode==='mysql'?'MySQL 实测':'有限模型'}} · {{repair.status}}</strong><p>{{repair.message}}</p><table class="result-table"><thead><tr><th>场景</th><th>人数 / 计数</th><th>交错数</th><th>结果</th></tr></thead><tbody><tr v-for="s in repair.scenarios" :key="s.name"><td>{{s.name}}</td><td>{{s.actual}} / {{s.counter}}</td><td>{{s.schedules}}</td><td>{{s.passed?'通过':'不通过'}}</td></tr></tbody></table></div></template>
 <div v-if="grading" class="grade-card" :class="grading.status" role="status"><strong>{{grading.status==='passed'?'核验通过':grading.status==='failed'?'需要进一步调查':'核验未完成'}}</strong><p>{{grading.message}}</p><ResultTable v-if="grading.expected" :table="grading.expected" :diff-rows="grading.diff?.expected" title="公开数据期望结果"/><ResultTable v-if="grading.actual" :table="grading.actual" :diff-rows="grading.diff?.actual" title="实际结果"/><button v-if="grading.status==='passed'&&nextTask&&nextTask.id!==selected" @click="selected=nextTask.id">继续调查 →</button></div>
 <section v-if="result" class="case-query-result"><div class="toolbar"><strong>调查结果 · {{result.table.rows.length}} 行</strong><button data-testid="pin-evidence" :disabled="!!lab.jobs['case-query']" @click="pin">固定为证据</button></div><ResultTable :table="result.table" title="冻结查询结果"/></section><TraceView v-if="trace" :trace="trace"/></section>
 <aside :class="['case-evidence-rail',{open:drawer}]" :role="drawer?'dialog':undefined" :aria-modal="drawer||undefined" aria-label="调查证据与结案清单" ref="drawerHost" tabindex="-1" @keydown.esc="drawer=false" @keydown="drawer&&drawerHost&&trapFocus($event,drawerHost)"><div class="rail-heading"><h2>调查证据 {{p.evidence.length}} / 20</h2><button class="drawer-close" @click="drawer=false">关闭</button></div><button class="board-launch" @click="boardOpen=true;drawer=false">打开完整调查板 ↗</button><p v-if="!p.evidence.length" class="empty">运行 SQL 后，在结果旁固定你的发现。</p><article v-for="(card,i) in p.evidence" :key="card.id" :class="['evidence-mini',{new:latestCard===card.id}]"><small>证据 {{String(i+1).padStart(2,'0')}} · {{card.task}}</small><strong>{{card.note||context?.tasks.find(t=>t.id===card.task)?.title||'调查发现'}}</strong><span>{{card.table.rows.length}} 行{{card.table.truncated?' · 节选':''}}</span><div><button @click="source(card.id)">来源 SQL</button><button @click="boardOpen=true">整理关系</button></div></article>
 <section class="case-conclusion"><h3>结案检查清单</h3><p v-if="!review" class="muted">正在核验当前证据…</p><button v-for="item in review?.items??[]" :key="item.id" class="checklist-item" :class="{done:item.passed}" @click="jump(item)"><span>{{item.passed?'✓':'○'}}</span>{{item.title}}</button><label v-if="mode==='expert'||(context?.stage??0)>=3">调查根因<select v-model="p.cause" @change="changed()"><option value="">尚未确定</option><option value="stale_read">读取旧值后覆盖写入</option><option value="duplicate_name">身份混淆</option><option value="null_count">NULL 计数</option></select></label><small>模型：{{p.model_strategy||'未通过'}}<br>MySQL：{{p.mysql_strategy||'未实测（可选）'}}</small><button class="primary" data-testid="close-case" :disabled="!review?.can_close||!!lab.jobs['case-close']" @click="close">重新核验并结案</button><strong v-if="closed" role="status">✓ 案件已结案</strong><button @click="restart">开始新一轮调查</button><details v-if="p.history.length"><summary>历史结论 {{p.history.length}}</summary><p v-for="h in p.history" :key="h.round">第 {{h.round+1}} 轮 · {{h.closed?'已结案':'调查中'}} · {{h.cause||'未确定根因'}} · {{h.evidence_count}} 张证据</p></details></section></aside></div>
 <div v-if="drawer" class="drawer-shade" @click="drawer=false"/>
 <EvidenceBoard v-if="boardOpen" :progress="p" @change="changed" @close="boardOpen=false" @source="source" @rerun="rerun" @remove="remove"/>

</div><div v-else class="empty">正在打开调查档案…</div></template>
